param([ValidateSet('core-build','core-test','fla-build')][string]$Action='core-build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-tiled-kkt-20260913';$seed='D:\projects\AIMA-public-float-subgroup-qk-20260913';$sha='62d5fd4309654c005eeeb0d376e3c348b4b2b535';$bundle='D:\projects\tiled-kkt-62d5fd4.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '0d2103a8934a8e8789a6b6f606bed7eef72c754a695cccf421c8652c505cc779'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\tiled-kkt';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\tiled_kkt_selftest.cpp';$exe=Join-Path $build 'tiled-kkt.exe';$provenance=Join-Path $build 'core-build-provenance.json'
$sourceInputs=@();$files=@($source,(Join-Path $repo 'scripts\baiying_build_fla_gdn.ps1'))
foreach($dir in @('native\providers\gdn','native\providers\moe_accumulator')){
 $files+=@(Get-ChildItem (Join-Path $repo $dir) -File|Where-Object {$_.Extension -in @('.h','.cpp')}|ForEach-Object {$_.FullName})
}
foreach($file in $files){$sourceInputs+=@{file=$file;sha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; generated KKT controls through q8192';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;purpose='Compare original 16-lane KKT with tiled scalar integer and prevalidated scalar float, preserving rounded beta*K, original K16 carry, upper triangle and later gating. Native numerical and real-model qualification required.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
switch($Action){
 'core-build'{
  if(Test-Path $exe){throw 'Executable exists'}
  $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
  $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=90
 }
 'core-test'{
  $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
  if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
  $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
  $spec.executable=$exe;$spec.arguments=@();$timeout=90
 }
 'fla-build'{
  $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
  $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_fla_gdn.ps1'),'-OutDir',(Join-Path $repo 'build\fla'),'-AotDir','D:\projects\AIMA-public-capture-20260910\build\fla-r20','-DppReduction','1','-CompactNormalize','1','-TimeoutSeconds','150');$timeout=180
 }
}
$specPath=Join-Path $build ($Action+'-spec-r1.json');$out=Join-Path $repo ('build\tiled-kkt-'+$Action+'-r1')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic failed'}
if($Action -eq 'core-build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}elseif($Action -eq 'core-test'){
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 if($reports.Count -ne 18){throw 'Incomplete KKT diagnostics'}
 foreach($report in $reports){if($report.raw_bit_mismatches -ne 0 -or -not $report.redzones_pass -or -not $report.immutable_inputs){throw 'KKT numerical or memory failure'}}
}

run-native-tiled-kkt-probes-r1.ps1.text:
param([ValidateSet(0,1,2)][int]$TiledKkt=2,[ValidateSet(64,65,7169)][int]$Tokens=64)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-tiled-kkt-20260913';$sha='62d5fd4309654c005eeeb0d376e3c348b4b2b535';$build=Join-Path $repo 'build\fla'
$ref='D:\projects\AIMA-public-canonical-normalize-20260913';$refSha='8f436db3520a356f6c6f435489a15a2081a655fc';$refDir=Join-Path $ref 'build\fla'
$metas=@()
foreach($root in @($repo,$ref)){
 $expected=if($root -eq $repo){$sha}else{$refSha}
 if((& git -C $root rev-parse HEAD).Trim() -ne $expected -or @(& git -C $root status --porcelain).Count -ne 0){throw 'Source mismatch'}
 $metaPath=Join-Path $root 'build\fla\build-provenance.json';$runName=if($root -eq $repo){'tiled-kkt-fla-build-r1'}else{'batch-fla-build-r1'};$runPath=Join-Path $root ('build\'+$runName+'\run-record.json')
 if($root -eq $ref -and ((Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'dda51b9e889cc570e2657f5a235c83b52b51762fadd2191c4757e3f3f5510fc0' -or (Get-FileHash $runPath -Algorithm SHA256).Hash.ToLowerInvariant() -ne '4fe2ec8716260509f449d36a1fc88dd751638c2559b568e76001ea10a3927ad3')){throw 'Qualified reference build changed'}
 $meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json;$run=[IO.File]::ReadAllText($runPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $expected -or $meta.dirty_tree -or $run.exit_code -ne 0 -or -not $run.host_checks_pass){throw 'Build not qualified'}
 foreach($a in $meta.artifacts){$file=if($a.name){$a.name}else{$a.file};if((Get-FileHash (Join-Path $root ('build\fla\'+$file)) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $a.sha256){throw 'Build artifact changed'}}
 foreach($a in $meta.sources){if((Get-FileHash $a.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $a.sha256){throw 'Build source changed'}}
 $metas+=@{commit=$expected;build_metadata_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant();build_run_sha256=(Get-FileHash $runPath -Algorithm SHA256).Hash.ToLowerInvariant();artifacts=$meta.artifacts}
}
$name='tiled-kkt-mode'+$TiledKkt+'-q'+$Tokens+'-probe-r1';$out=Join-Path $repo ('build\'+$name);$specPath=Join-Path $repo ('build\tail-specs\'+$name+'.json')
foreach($p in @($out,$specPath)){if(Test-Path $p){throw 'Existing evidence'}}
$tables=@(
 @{path='D:\projects\sm121-exp2-negative-f490940d.bin';sha256='f490940df2bd80421159a96424c3e922330b7ca120d5ae7b629a973b9183730b'},
 @{path='D:\projects\sm121-rsqrt-positive-ca0230a8.bin';sha256='ca0230a8bae9bd101ac368f8a7c34007cda637df6513dbe4714253c36b940850'}
)
foreach($table in $tables){if((Get-FileHash $table.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $table.sha256){throw 'Arithmetic table changed'}}
$environment=[ordered]@{QRT_FLA_GDN_TILED_KKT=[string]$TiledKkt;QRT_FLA_GDN_COOPERATIVE_EXACT='1';QRT_FLA_GDN_BATCHED_EXACT='1';QRT_FLA_GDN_SMOKE_REQUIRE_REFERENCE_EXACT='1';QRT_FLA_GDN_NORM_BLACKWELL='1';QRT_FLA_GDN_KKT_BLACKWELL='1';QRT_FLA_GDN_INVERSE_BLACKWELL='1';QRT_FLA_GDN_WU_BLACKWELL='1';QRT_FLA_GDN_STATE_BLACKWELL='1';QRT_FLA_GDN_OUTPUT_BLACKWELL='1';QRT_FLA_GDN_SYNC_EACH_STAGE='0';QRT_FLA_GDN_SM121_EXP2_TABLE=$tables[0].path;QRT_FLA_GDN_SM121_RSQRT_TABLE=$tables[1].path;QRT_FLA_GDN_SMOKE_INPUT_DIR='';QRT_FLA_GDN_DUMP_Q64_DIR='';QRT_FLA_GDN_SMOKE_DUMP_PREFIX='';QRT_FLA_GDN_CAPTURE_FIRST_DIR=''}
$audit=$null;$auditSha=$null
if($Tokens -eq 7169){
 $inputDir='D:\projects\AIMA-public-fla-20260909\build\fla-real-l0-input';$auditPath=Join-Path $inputDir 'fla-real-l0-input-audit.json';$audit=[IO.File]::ReadAllText($auditPath)|ConvertFrom-Json
 foreach($key in @('q','k','v','g','beta')){$a=$audit.reference_files.$key;$path=Join-Path $inputDir ([IO.Path]::GetFileName($a.path));if((Get-Item $path).Length -ne $a.bytes -or (Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $a.sha256){throw 'Captured component input changed'}}
 if(-not $audit.captured_seed_exact_zero -or -not $audit.verification.output_bit_exact -or -not $audit.verification.state_bit_exact){throw 'Invalid original capture boundary'}
 $auditSha=(Get-FileHash $auditPath -Algorithm SHA256).Hash.ToLowerInvariant();$environment['QRT_FLA_GDN_SMOKE_INPUT_DIR']=$inputDir
}
foreach($key in $environment.Keys){[Environment]::SetEnvironmentVariable($key,[string]$environment[$key],'Process')}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$spec=[ordered]@{executable=(Join-Path $build ('q'+$Tokens+'-fla-smoke.exe'));working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();model=$(if($Tokens -eq 7169){'GB10 Qwen3.6-35B-A3B BF16 captured layer-0 q7169 operands'}else{'synthetic component operands'});model_loaded=$false;inference_acceptance=$false;arguments=@($build,(Join-Path $build 'qrt_fla_chunk_gdn_provider.dll'),$refDir,(Join-Path $refDir 'qrt_fla_chunk_gdn_provider.dll'));components=$metas;input_audit=$audit;input_audit_sha256=$auditSha;tables=$tables;environment=$environment;tiled_kkt=$TiledKkt;purpose='Compare every output and final state bit against the qualified old exact component, then verify async parity; this is component evidence only'}
$null=New-Item -ItemType Directory -Path (Split-Path -Parent $specPath) -Force
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds 75|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
$stdout=[IO.File]::ReadAllText((Join-Path $out 'product.stdout.jsonl'));Write-Output $stdout
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass -or $stdout -notmatch 'reference_exact_required=1 output_reference_bit_mismatches=0 state_reference_bit_mismatches=0'){throw 'Exact component or host check failed'}
